/// <reference types="svelte" />
/**
 * Store: team — see CARTOGRAPHY.md
 * Consumers: Header, TeamPanel, TeamList, PensionList, StorageGrid
 */

import { facade } from '@bus/facade';
import { isFacadeDebugEnabled } from '../bus/facadeDebug.js';
import { devLog } from '../lib/devLog.ts';
import { GameEventType as Evt } from '../bus/events.js';
import type {
  CreatureSnapshot,
  HeaderStatKey,
  StorageCardSnapshot,
  TeamHeaderStatsSnapshot,
  TeamSnapshot,
} from '../bus/snapshots.js';
import type { ResonanceTeamPreview } from '../lib/regionalResonance.ts';
import { resonancePreviewSignature } from '../lib/regionalResonance.ts';
import type { GameRuntime } from '../types/game.js';
import { buildFaintedTeamIndices } from '../lib/faintedThisCombat.ts';
import {
  patchCreatureVolatileFields,
  applyStorageRosterUpdate,
  storageRosterPublishWouldChange,
  teamRosterIdentityEqual,
  teamSynergyTypesSignature,
  teamPassiveTalentsSignature,
} from './storeUtils.js';
import { storageSortStacksEqual } from '../lib/storageSortUtils.js';
import type { StorageSortEntry } from '../lib/storageSortUtils.js';
import { registerTeamSnapshotGetter } from './teamSnapshotGetter.js';
import { captureUiScrollPositions, restoreUiScrollPositions } from '../lib/uiScrollPreserve.ts';
import { deferIfMobileScrolling } from '../lib/mobileScrollGate.ts';
import { mapRosterSlots } from '../bus/gameFacade.js';

const EMPTY_STATS: TeamSnapshot['teamStats'] = {
  hp: 0, attack: 0, spattack: 0, defense: 0, spdefense: 0, speed: 0,
};

const EMPTY_GAINS: TeamSnapshot['passiveGainsPerSec'] = { ...EMPTY_STATS };

const EMPTY_BOOSTED: Record<HeaderStatKey, boolean> = {
  hp: false, attack: false, spattack: false, defense: false, spdefense: false, speed: false,
};

const EMPTY_LABELS: TeamSnapshot['labels'] = {
  levelShort: 'Lvl',
  viewDetails: 'View details',
  teamContributionPrefix: 'Contribution',
  pensionContributionPrefix: 'Contribution',
};

class TeamStore {
  playerTeam: TeamSnapshot['playerTeam'] = $state([]);
  pension: TeamSnapshot['pension'] = $state([]);
  storageCount: number = $state(0);
  teamStats: TeamSnapshot['teamStats'] = $state({ ...EMPTY_STATS });
  passiveGainsPerSec: TeamSnapshot['passiveGainsPerSec'] = $state({ ...EMPTY_GAINS });
  maxTeamSize: number = $state(6);
  maxPensionSlots: number = $state(0);
  teamCountLabel: string = $state('0/6');
  pensionCountLabel: string = $state('0/0');
  headerStatBoosted: Record<HeaderStatKey, boolean> = $state({ ...EMPTY_BOOSTED });
  activeCreatureIndex: number = $state(0);
  faintedTeamIndices: number[] = $state([]);
  teamSpritesOnly: boolean = $state(false);
  teamContributionRatePercent: string = $state('10');
  pensionTransferRatePercent: string = $state('0');
  labels: TeamSnapshot['labels'] = $state({ ...EMPTY_LABELS });
  storageRoster: StorageCardSnapshot[] = $state([]);
  storageFilteredCountLabel: string = $state('0/0');
  storageShowEmptyFiltered: boolean = $state(false);
  storageSortStack: StorageSortEntry[] = $state([]);
  storageSortByBaseStats: boolean = $state(false);
  /** Bumps when player team type composition changes (synergy button). */
  synergyTypesSignature: string = $state('');
  passiveTalentsSignature: string = $state('');
  resonancePreview: ResonanceTeamPreview | null = $state(null);
  ultimateSlotUnlocked: boolean = $state(false);
  ultimateSlot: CreatureSnapshot | null = $state(null);
  ultimateSlotTransferPercent: string = $state('1');
  ultimateSlotBonus: TeamSnapshot['ultimateSlotBonus'] = $state({ ...EMPTY_STATS });
}

export const team = new TeamStore();

function statBlockEqual(a: TeamSnapshot['teamStats'], b: TeamSnapshot['teamStats']): boolean {
  return (
    a.hp === b.hp &&
    a.attack === b.attack &&
    a.spattack === b.spattack &&
    a.defense === b.defense &&
    a.spdefense === b.spdefense &&
    a.speed === b.speed
  );
}

function headerBoostedEqual(
  boosted: Record<HeaderStatKey, boolean>,
  bBoosted: Record<HeaderStatKey, boolean>,
): boolean {
  for (const k of Object.keys(boosted) as HeaderStatKey[]) {
    if (boosted[k] !== bBoosted[k]) return false;
  }
  return true;
}

function faintedEqual(a: number[], b: number[]): boolean {
  if (a.length !== b.length) return false;
  for (let i = 0; i < a.length; i++) {
    if (a[i] !== b[i]) return false;
  }
  return true;
}


/** Returns replacement array when identity/order changes; otherwise patches volatile fields in place. */
function applyCreatureRoster(
  current: CreatureSnapshot[],
  incoming: CreatureSnapshot[],
): CreatureSnapshot[] | null {
  if (current.length !== incoming.length || !teamRosterIdentityEqual(current, incoming)) {
    return incoming.map((c) => ({ ...c }));
  }
  for (let i = 0; i < incoming.length; i++) {
    const cur = current[i];
    const inc = incoming[i];
    if (cur === undefined || inc === undefined) continue;
    const patched = patchCreatureVolatileFields(cur, inc);
    if (patched !== cur) current[i] = patched;
  }
  return null;
}

function applyTeamHeaderStats(h: TeamHeaderStatsSnapshot): void {
  if (!statBlockEqual(h.teamStats, team.teamStats)) team.teamStats = h.teamStats;
  if (!statBlockEqual(h.passiveGainsPerSec, team.passiveGainsPerSec)) {
    team.passiveGainsPerSec = h.passiveGainsPerSec;
  }
  if (!headerBoostedEqual(team.headerStatBoosted, h.headerStatBoosted)) {
    team.headerStatBoosted = h.headerStatBoosted;
  }
}

function refreshSynergyTypesSignature(): void {
  const sig = teamSynergyTypesSignature(team.playerTeam);
  if (sig !== team.synergyTypesSignature) team.synergyTypesSignature = sig;
}

function refreshPassiveTalentsSignature(): void {
  const sig = teamPassiveTalentsSignature(team.playerTeam);
  if (sig !== team.passiveTalentsSignature) team.passiveTalentsSignature = sig;
}

function applyTeamSnapshot(t: TeamSnapshot): void {
    const scrollSaved = captureUiScrollPositions();
    const nextTeam = applyCreatureRoster(team.playerTeam, t.playerTeam);
  if (nextTeam) {
    if (isFacadeDebugEnabled()) {
      devLog('[team] full roster replace', {
        prev: team.playerTeam.map((c) => c.uid),
        next: nextTeam.map((c) => c.uid),
      });
    }
    team.playerTeam = nextTeam;
  }
  const nextPension = applyCreatureRoster(team.pension, t.pension);
  if (nextPension) {
    if (isFacadeDebugEnabled()) {
      devLog('[team] full pension roster replace', {
        prev: team.pension.map((c) => c.uid),
        next: nextPension.map((c) => c.uid),
      });
    }
    team.pension = nextPension;
  }
  if (t.storageCount !== team.storageCount) team.storageCount = t.storageCount;
  if (!statBlockEqual(t.teamStats, team.teamStats)) team.teamStats = t.teamStats;
  if (!statBlockEqual(t.passiveGainsPerSec, team.passiveGainsPerSec)) {
    team.passiveGainsPerSec = t.passiveGainsPerSec;
  }
  if (t.maxTeamSize !== team.maxTeamSize) team.maxTeamSize = t.maxTeamSize;
  if (t.maxPensionSlots !== team.maxPensionSlots) team.maxPensionSlots = t.maxPensionSlots;
  if (t.teamCountLabel !== team.teamCountLabel) team.teamCountLabel = t.teamCountLabel;
  if (t.pensionCountLabel !== team.pensionCountLabel) team.pensionCountLabel = t.pensionCountLabel;
  if (!headerBoostedEqual(team.headerStatBoosted, t.headerStatBoosted)) {
    team.headerStatBoosted = t.headerStatBoosted;
  }
  if (t.activeCreatureIndex !== team.activeCreatureIndex) team.activeCreatureIndex = t.activeCreatureIndex;
  if (!faintedEqual(team.faintedTeamIndices, t.faintedTeamIndices)) {
    team.faintedTeamIndices = t.faintedTeamIndices;
  }
  if (t.teamSpritesOnly !== team.teamSpritesOnly) team.teamSpritesOnly = t.teamSpritesOnly;
  if (t.teamContributionRatePercent !== team.teamContributionRatePercent) {
    team.teamContributionRatePercent = t.teamContributionRatePercent;
  }
  if (t.pensionTransferRatePercent !== team.pensionTransferRatePercent) {
    team.pensionTransferRatePercent = t.pensionTransferRatePercent;
  }
  if (
    t.labels.levelShort !== team.labels.levelShort ||
    t.labels.viewDetails !== team.labels.viewDetails ||
    t.labels.teamContributionPrefix !== team.labels.teamContributionPrefix ||
    t.labels.pensionContributionPrefix !== team.labels.pensionContributionPrefix
  ) {
    team.labels = t.labels;
  }
  if (storageRosterPublishWouldChange(team.storageRoster, t.storageRoster)) {
    team.storageRoster = t.storageRoster;
  }
  if (t.storageFilteredCountLabel !== team.storageFilteredCountLabel) {
    team.storageFilteredCountLabel = t.storageFilteredCountLabel;
  }
  if (t.storageShowEmptyFiltered !== team.storageShowEmptyFiltered) {
    team.storageShowEmptyFiltered = t.storageShowEmptyFiltered;
  }
  if (!storageSortStacksEqual(team.storageSortStack, t.storageSortStack ?? [])) {
    team.storageSortStack = (t.storageSortStack ?? []).map((entry) => ({ ...entry }));
  }
  if (!!t.storageSortByBaseStats !== team.storageSortByBaseStats) {
    team.storageSortByBaseStats = !!t.storageSortByBaseStats;
  }
  const previewSig = resonancePreviewSignature(t.resonancePreview);
  const currentPreviewSig = resonancePreviewSignature(team.resonancePreview);
  if (previewSig !== currentPreviewSig) {
    team.resonancePreview = t.resonancePreview;
  }
  if (t.ultimateSlotUnlocked !== team.ultimateSlotUnlocked) {
    team.ultimateSlotUnlocked = t.ultimateSlotUnlocked;
  }
  const ultUid = team.ultimateSlot?.uid ?? null;
  const nextUltUid = t.ultimateSlot?.uid ?? null;
  if (ultUid !== nextUltUid) {
    team.ultimateSlot = t.ultimateSlot ? { ...t.ultimateSlot } : null;
  } else if (t.ultimateSlot && team.ultimateSlot) {
    const patched = patchCreatureVolatileFields(team.ultimateSlot, t.ultimateSlot);
    if (patched !== team.ultimateSlot) team.ultimateSlot = patched;
  }
  if (t.ultimateSlotTransferPercent !== team.ultimateSlotTransferPercent) {
    team.ultimateSlotTransferPercent = t.ultimateSlotTransferPercent;
  }
  if (!statBlockEqual(t.ultimateSlotBonus, team.ultimateSlotBonus)) {
    team.ultimateSlotBonus = t.ultimateSlotBonus;
  }
  refreshSynergyTypesSignature();
  refreshPassiveTalentsSignature();
  restoreUiScrollPositions(scrollSaved);
}

function applyStorageSortStack(stack: StorageSortEntry[], byBaseStats?: boolean): void {
  if (!storageSortStacksEqual(team.storageSortStack, stack)) {
    team.storageSortStack = stack.map((entry) => ({ ...entry }));
  }
  if (typeof byBaseStats === 'boolean' && byBaseStats !== team.storageSortByBaseStats) {
    team.storageSortByBaseStats = byBaseStats;
  }
}

function applyStoragePayload(
  roster: StorageCardSnapshot[],
  filteredLabel: string,
  showEmpty: boolean,
): void {
  const scrollSaved = captureUiScrollPositions();
  if (storageRosterPublishWouldChange(team.storageRoster, roster)) {
    const nextRoster = applyStorageRosterUpdate(team.storageRoster, roster);
    if (nextRoster) team.storageRoster = nextRoster;
  }
  if (filteredLabel !== team.storageFilteredCountLabel) {
    team.storageFilteredCountLabel = filteredLabel;
  }
  if (showEmpty !== team.storageShowEmptyFiltered) team.storageShowEmptyFiltered = showEmpty;
  restoreUiScrollPositions(scrollSaved);
}

function currentTeamSnapshot(): TeamSnapshot {
  return {
    playerTeam: team.playerTeam,
    pension: team.pension,
    storageCount: team.storageCount,
    teamStats: team.teamStats,
    passiveGainsPerSec: team.passiveGainsPerSec,
    maxTeamSize: team.maxTeamSize,
    maxPensionSlots: team.maxPensionSlots,
    teamCountLabel: team.teamCountLabel,
    pensionCountLabel: team.pensionCountLabel,
    headerStatBoosted: team.headerStatBoosted,
    activeCreatureIndex: team.activeCreatureIndex,
    faintedTeamIndices: team.faintedTeamIndices,
    teamSpritesOnly: team.teamSpritesOnly,
    teamContributionRatePercent: team.teamContributionRatePercent,
    pensionTransferRatePercent: team.pensionTransferRatePercent,
    labels: team.labels,
    storageRoster: team.storageRoster,
    storageFilteredCountLabel: team.storageFilteredCountLabel,
    storageShowEmptyFiltered: team.storageShowEmptyFiltered,
    storageSortStack: team.storageSortStack.map((entry) => ({ ...entry })),
    storageSortByBaseStats: team.storageSortByBaseStats,
    resonancePreview: team.resonancePreview,
    ultimateSlotUnlocked: team.ultimateSlotUnlocked,
    ultimateSlot: team.ultimateSlot,
    ultimateSlotTransferPercent: team.ultimateSlotTransferPercent,
    ultimateSlotBonus: team.ultimateSlotBonus,
  };
}

registerTeamSnapshotGetter(currentTeamSnapshot);

/** Sync hydrate (e.g. after Svelte mount) — bypasses facade debounce. */
export function hydrateTeamStore(snapshot: TeamSnapshot): void {
  applyTeamSnapshot(snapshot);
}

function applyTeamCombatMeta(gm: GameRuntime): void {
  const nextActive = gm.activeCreatureIndex ?? 0;
  if (nextActive !== team.activeCreatureIndex) team.activeCreatureIndex = nextActive;

  const fainted = buildFaintedTeamIndices(gm);
  if (!faintedEqual(team.faintedTeamIndices, fainted)) {
    team.faintedTeamIndices = fainted;
  }
}

/** Combat-only meta (active slot, fainted set) without rebuilding roster snapshots. */
export function syncTeamCombatMeta(gm: GameRuntime): void {
  deferIfMobileScrolling('teamCombatMeta', () => {
    const scrollSaved = captureUiScrollPositions();
    applyTeamCombatMeta(gm);
    restoreUiScrollPositions(scrollSaved);
  });
}

/** Patch team roster volatiles after combat without a full TEAM_CHANGED publish. */
export function syncTeamVolatilesAfterCombat(gm: GameRuntime): void {
  deferIfMobileScrolling('teamCombatMeta', () => {
    const scrollSaved = captureUiScrollPositions();
    applyTeamCombatMeta(gm);

    const incomingTeam = mapRosterSlots(gm, gm.playerTeam || [], 'team');
    const nextTeam = applyCreatureRoster(team.playerTeam, incomingTeam);
    if (nextTeam) {
      team.playerTeam = nextTeam;
    }

    restoreUiScrollPositions(scrollSaved);
  });
}

facade.subscribe(Evt.TEAM_HEADER_STATS, (evt) => {
  if (!('header' in evt)) return;
  deferIfMobileScrolling('teamHeader', () => applyTeamHeaderStats(evt.header));
});

facade.subscribe(Evt.TEAM_CHANGED, (evt) => {
  if (!('team' in evt)) return;
  deferIfMobileScrolling('team', () => applyTeamSnapshot(evt.team));
});

facade.subscribe(Evt.STORAGE_CHANGED, (evt) => {
  if (!('storageRoster' in evt)) return;
  deferIfMobileScrolling('storage', () => applyStoragePayload(
    evt.storageRoster,
    evt.storageFilteredCountLabel,
    evt.storageShowEmptyFiltered,
  ));
});

facade.subscribe(Evt.STORAGE_SORT_CHANGED, (evt) => {
  if (!('storageSortStack' in evt)) return;
  applyStorageSortStack(evt.storageSortStack, evt.storageSortByBaseStats);
});
